// Usage: node make-poster.js fares.json out.png
// Fares in the JSON are the airline's all-in fares; the service fee is added silently.
const fs = require('fs');
const { chromium } = require('playwright');

const data = JSON.parse(fs.readFileSync(process.argv[2] || 'fares.json', 'utf8'));
const out = process.argv[3] || 'airfare-promo.png';
const fee = data.serviceFee;
const peso = n => '₱' + (n + fee).toLocaleString('en-US');

const block = ([from, to, outbound, inbound]) => `
  <div class="route">
    <div class="row"><span>${from} – ${to}</span><b>${peso(outbound)}</b></div>
    <div class="row"><span>${to} – ${from}</span><b>${peso(inbound)}</b></div>
  </div>`;

const html = `<!doctype html><html><head><meta charset="utf-8"><style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { width: 1080px; height: 1350px; font-family: 'DejaVu Sans', sans-serif; color: #fff;
    background: linear-gradient(180deg, rgba(20,28,105,.55), rgba(20,28,105,.15) 40%, rgba(20,28,105,.65)), url(data:image/png;base64,) center/cover;
    position: relative; overflow: hidden; }
  .skyline { position: absolute; left: 0; right: 0; bottom: 0; height: 360px;
    background:
      linear-gradient(transparent 0 30%, rgba(10,20,50,.85) 30%) 0 0/60px 100%,
      linear-gradient(transparent 0 55%, rgba(10,20,50,.9) 55%) 30px 0/90px 100%,
      linear-gradient(transparent 0 15%, rgba(15,25,60,.8) 15%) 70px 0/140px 100%;
    opacity: .55; }
  header { text-align: center; padding: 34px 40px 10px; position: relative; }
  .brand { position: absolute; top: 28px; right: 40px; width: 120px; height: 120px; border-radius: 50%;
    background: #fff; color: #1d3fa8; display: flex; align-items: center; justify-content: center;
    font-weight: 900; font-size: 26px; box-shadow: 0 6px 20px rgba(0,0,0,.35); letter-spacing: 1px; }
  .badge { position: absolute; top: 28px; left: 40px; width: 120px; height: 120px; border-radius: 50%;
    background: #ffc83d; color: #1a1a1a; display: flex; flex-direction: column; align-items: center;
    justify-content: center; font-weight: 900; font-size: 20px; line-height: 1.1; text-align: center;
    box-shadow: 0 6px 20px rgba(0,0,0,.35); transform: rotate(-10deg); }
  h1 { font-size: 64px; font-weight: 900; letter-spacing: 2px; text-shadow: 0 4px 0 #1a2a6c, 0 8px 18px rgba(0,0,0,.4); }
  .sub { font-size: 19px; font-weight: 700; margin-top: 10px; text-shadow: 0 2px 6px rgba(0,0,0,.5); }
  .sub2 { font-size: 16px; margin-top: 6px; color: #ffe9a8; font-weight: 700; }
  .cols { display: flex; gap: 22px; padding: 18px 40px 0; position: relative; }
  .col { flex: 1; background: rgba(255,255,255,.92); border-radius: 22px; padding: 12px 20px;
    box-shadow: 0 10px 30px rgba(0,0,0,.3); color: #12224f; }
  .route { padding: 18px 0; border-bottom: 1px dashed #b9c3e6; }
  .route:last-child { border-bottom: 0; }
  .row { display: flex; justify-content: space-between; font-size: 28px; line-height: 1.35; }
  .row span { font-weight: 700; white-space: nowrap; }
  .row b { color: #d6261f; font-weight: 900; }
  footer { position: absolute; bottom: 26px; left: 40px; right: 40px; text-align: center; }
  .cta { display: inline-block; background: #ff7a00; color: #fff; font-weight: 900; font-size: 34px;
    padding: 14px 44px; border-radius: 50px; box-shadow: 0 6px 0 #b85400, 0 10px 24px rgba(0,0,0,.35); }
  .fine { font-size: 15px; margin-top: 14px; text-shadow: 0 1px 4px rgba(0,0,0,.6); }
  .sample { position: absolute; top: 45%; left: -10%; width: 120%; text-align: center; transform: rotate(-24deg);
    font-size: 110px; font-weight: 900; color: rgba(214,38,31,.35); letter-spacing: 6px; pointer-events: none; }
</style></head><body>
  <header>
    <div class="badge" style="background:#fff;transform:none;width:230px;height:120px;border-radius:24px;left:30px"><img src="data:image/png;base64," style="width:200px"></div>
    <div class="brand"><img src="data:image/png;base64," style="height:96px"></div>
    <h1>CEBU PACIFIC<br>SEAT SALE</h1>
    <div class="sub">${data.travelDate}</div>
    <div class="sub2">ALL-IN FARES • 7KG HAND CARRY • TAXES &amp; FEES INCLUDED • PM FOR FAST TRANSACTION</div>
  </header>
  <div class="cols">
    <div class="col">${data.left.map(block).join('')}</div>
    <div class="col">${data.right.map(block).join('')}</div>
  </div>
  <footer>
    <div class="cta">BOOK YOUR TICKET NOW! ✈</div>
    <div class="fine">One-way fares per person via Cebu Pacific. Rates subject to change and seat availability until ticketed. Message Biahes on Facebook • 0956 382 3906</div>
  </footer>
  ${data.sample ? '<div class="sample">SAMPLE – OLD RATES</div>' : ''}
</body></html>`;

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1080, height: 1350 } });
  await page.setContent(html);
  await page.screenshot({ path: out });
  await browser.close();
  console.log('saved', out);
})();
